const input = $input.first().json || {};
const task = String(input.taches || input.task || '').trim() || 'Rediger un message de prospection';
const priority = String(input.priorite || 'normale');
const outputType = String(input.output_type || 'message_vente');

function detectSector(text) {
 const lower = text.toLowerCase();
 if (lower.includes('garage') || lower.includes('automobile') || lower.includes('mécanique') || lower.includes('mecanique')) return 'garages automobiles';
 if (lower.includes('dentaire') || lower.includes('dentiste')) return 'cliniques dentaires';
 if (lower.includes('clinique')) return 'cliniques';
 if (lower.includes('restaurant')) return 'restaurants';
 return 'PME de services';
}

const sector = detectSector(task);
const offer = sector === 'garages automobiles'
 ? 'reception IA, relances automatisees et suivi des demandes de rendez-vous ou de soumissions'
 : 'reception IA, automatisation des suivis et workflows simples pour reduire les taches repetitives';

const message = `Bonjour, je vous contacte parce que Cadence Numerique aide les ${sector} a mieux gerer les appels, les demandes entrantes et les suivis grace a des agents IA et des automatisations simples.\n\nL'objectif est concret : reduire les appels manques, accelerer les reponses aux clients et liberer du temps administratif sans remplacer votre equipe.\n\nSeriez-vous ouvert a un court echange de 15 minutes pour voir si une reception IA ou un workflow de suivi pourrait etre utile dans votre contexte?`;

const relanceJ3 = `Bonjour, je me permets une courte relance. Plusieurs ${sector} perdent du temps sur les appels manques, les suivis et les demandes repetitives. Cadence peut aider a automatiser une partie de ce travail sans complexifier vos operations. Est-ce qu'un echange rapide cette semaine serait possible?`;
const relanceJ7 = `Bonjour, derniere petite relance de ma part. Si ameliorer la gestion des appels et des suivis clients devient une priorite, je peux vous preparer un exemple concret adapte a votre activite.`;

const sheetResult = [
 `Message de prospection - ${sector}`,
 '',
 message,
 '',
 'Relance J+3:',
 relanceJ3,
 '',
 'Relance J+7:',
 relanceJ7,
 '',
 'Prochaine action: valider le message, choisir 5 a 10 prospects prioritaires, puis personnaliser la premiere ligne.'
].join('\n');

return [{
 json: {
 workflow: 'Cadence - Sales AI',
 status: 'done',
 mode: 'deterministic_sales_message',
 task,
 priority,
 outputType,
 sheet_result: sheetResult,
 priorite_commerciale: priority === 'haute' ? 'haute' : 'moyenne',
 prospect_ou_segment_concerne: sector,
 raisons_de_priorisation: [
 'Segment local avec appels et suivis frequents',
 'Potentiel clair pour automatiser la reception, les relances et les demandes repetitives',
 'Approche commerciale simple a personnaliser apres validation humaine'
 ],
 offre_cadence_pertinente: offer,
 message_de_contact_brouillon: message,
 sequence_relance: {
 j1: message,
 j3: relanceJ3,
 j7: relanceJ7
 },
 objections_et_reponses: [
 {
 objection: 'Nous avons deja quelqu un qui repond au telephone.',
 reponse: 'Justement, l IA peut soutenir l equipe lors des periodes chargees, hors heures ouvrables ou pour les demandes repetitives.'
 },
 {
 objection: 'C est surement trop complexe.',
 reponse: 'L approche peut commencer par un seul cas simple : appels manques, rappels ou demandes de rendez-vous.'
 },
 {
 objection: 'Nous ne voulons pas perdre le contact humain.',
 reponse: 'Le but est de garder l humain pour les echanges importants et de deleguer seulement les taches repetitives.'
 }
 ],
 prochaine_action_recommandee: 'Valider le message, choisir 5 a 10 prospects prioritaires, puis personnaliser la premiere ligne pour chaque entreprise.',
 action_hubspot: 'aucune',
 guardrails: [
 'Aucun courriel envoye automatiquement',
 'Aucun deal HubSpot cree automatiquement',
 'Message brouillon a valider par Ham avant utilisation'
 ],
 completedAt: new Date().toISOString()
 }
}];
